//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Returns whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

#[cfg(test)]
mod tests {
    use super::RetryError;

    #[test]
    fn classifies_error_variants() {
        assert!(RetryError::Transient("temporary".into()).is_transient());
        assert!(!RetryError::Permanent("invalid".into()).is_transient());
    }
}

//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Creates a retry configuration with a bounded exponential delay policy.
    pub const fn new(max_attempts: u32, base_delay_ms: u64, max_delay_ms: u64) -> Self {
        Self {
            max_attempts,
            base_delay_ms,
            max_delay_ms,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn new_sets_policy_values() {
        assert_eq!(
            RetryConfig::new(4, 25, 100),
            RetryConfig {
                max_attempts: 4,
                base_delay_ms: 25,
                max_delay_ms: 100,
            }
        );
    }
}

//! Injected sleeper so tests never really wait.
pub trait Sleeper {
    fn sleep_ms(&mut self, ms: u64);
}

/// Records every requested delay instead of waiting.
#[derive(Debug, Default)]
pub struct FakeSleeper {
    pub sleeps: Vec<u64>,
}

impl Sleeper for FakeSleeper {
    fn sleep_ms(&mut self, ms: u64) {
        self.sleeps.push(ms);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    let max_attempts = config.max_attempts.max(1);
    let mut attempts = 0;
    let mut delay_ms = config.base_delay_ms.min(config.max_delay_ms);

    loop {
        attempts += 1;
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if !error.is_transient() || attempts >= max_attempts => {
                return Err(error);
            }
            Err(_) => {
                sleeper.sleep_ms(delay_ms);
                delay_ms = delay_ms.saturating_mul(2).min(config.max_delay_ms);
            }
        }
    }
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    #[test]
    fn retries_transient_errors_with_bounded_exponential_delays() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&RetryConfig::new(5, 10, 25), &mut sleeper, || {
            calls += 1;
            if calls < 5 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 5);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25, 25]);
    }

    #[test]
    fn permanent_error_returns_without_sleeping() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&RetryConfig::new(5, 10, 100), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("bad input".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn max_attempts_includes_first_call() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;
        let result = run_job(&RetryConfig::new(3, 1, 10), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("temporary".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("temporary".into())));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![1, 2]);
    }

    #[test]
    fn zero_attempt_budget_still_makes_one_call() {
        let mut sleeper = FakeSleeper::default();
        let result = run_job(&RetryConfig::new(0, 1, 10), &mut sleeper, || {
            Err(RetryError::Permanent("called".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("called".into())));
        assert!(sleeper.sleeps.is_empty());
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failure_then_succeeds() {
    let mut sleeper = FakeSleeper::default();
    let mut attempts = 0;

    let result = run_job(&RetryConfig::new(3, 5, 20), &mut sleeper, || {
        attempts += 1;
        match attempts {
            1 => Err(RetryError::Transient("temporary outage".into())),
            _ => Ok(()),
        }
    });

    assert_eq!(result, Ok(()));
    assert_eq!(attempts, 2);
    assert_eq!(sleeper.sleeps, vec![5]);
}
